head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
//사이버정보분석팀일경우 팀코드가 시장마다 다르기 때문에 상위부서코드로 넣어준다. 20240510
if (scwin.gDepCd.substring(0, 2) == '5B') {
    scwin.gDepCd = '5B10';
}
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.mode = "I"; //'I' : 전송전, T 전송후 
scwin.key_row = frame.opener.scwin.key_row;
$c.info.js_emp_no; //담당자코드
$c.info.js_emp_nm; //담당자명

scwin.time_no; //부서위치
scwin.time_field; //통보시각 or 접수시각

scwin.key_dep_cd; //담당자선택시 부서코드
scwin.key_ld_mkt_tp_cd;
scwin.vScrenID = 'ULDSTF10807.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_init = function() {
    $c.stf.showObj(txb_ISUR_CD, false);
    $c.stf.showObj(txb_NOTI_SEQ, false);
    $c.stf.showObj(txb_MODE, false);
    $c.stf.showObj(txb_EMP_NO, false);
    $c.stf.showObj(txb_NOTI_DDTM, false);
    $c.stf.showObj(txb_LD_MKT_TP_CD, false);
    for (var i = 1; i < 3; i++) {
        $c.stf.showObj(eval("txb_ACPT_NO" + i), false);
        $c.stf.showObj(eval("txb_DEP_CD" + i), false);
        $c.stf.showObj(eval("txb_NOTI_EMP_NO" + i), false);
        $c.stf.showObj(eval("txb_ACPT_EMP_NO" + i), false);

        //시장감시부일때만 '공시시각','반송사유' 를 보여주고 다른팀일때 보여주지 않는다.
        if (scwin.gDepCd != '5B10') {
            if (i == 1) {
                $c.stf.showObj(label_15, false);
                panel_1.style.height = 408;
                panel_2.style.height = 138;
                label_24.style.top = 394;
                //btn_Cancel.style.top = 382;

                $c.stf.showObj(btn_Delete, false);
                $c.stf.showObj(btn_Transmit, false);
            }
            $c.stf.showObj(eval("txb_DISCLS_DDTM" + i), false);
            eval("txb_NOTI_EMP_NM" + i).style.backgroundColor = '#b9d4f7';
            eval("txb_NOTI_DDTM" + i).style.backgroundColor = '#b9d4f7';
            eval("txb_ACPT_EMP_NM" + i).style.backgroundColor = '#b9d4f7';
            eval("txb_REMK" + i).style.backgroundColor = '#b9d4f7';
        }
    }
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    var noti_ddtm = $c.stf.getObjectValue(txb_NOTI_DDTM);
    if (noti_ddtm == '') {
        //전송전 입력모드
        scwin.mode = 'I';
        scwin.fn_setPage();
    } else {
        //전송후 각담당자 입력모드
        scwin.mode = 'T';
        txb_INQDISCLS_REQ_CONTN.style.backgroundColor = '#b9d4f7';
        txb_INQDISCLS_REQ_CONTN.setReadOnly(true);
        txb_REMK.style.backgroundColor = '#b9d4f7';
        txb_REMK.setReadOnly(true);
        img_com_srch.setDisabled(true);
    }

    //데티어가 없을시 데이터로우를 생성해줘야 한다.
    if ($c.stf.getObjectValue(txb_COM_ABBRV) == '') {
        scwin.fn_SetCode();
    }
};
scwin.fn_SetCode = function() {
    dts_Master.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ONLINE_NOTICE_MASTER";
    dts_Master.Reset();
    dts_Master.insertRow();
    dts_Sub.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=TEL_NOTICE_SUB";
    dts_Sub.Reset();
    dts_Sub.insertRow();
};


//이벤트에 따라서 화면 리드온리 및 입력필드를 설정한다.
scwin.fn_setPage = function() {
    var halt_yn = $c.stf.getObjectValue(rdo_HALT_YN);
    var noti_ddtm = $c.stf.getObjectValue(txb_NOTI_DDTM);
    if (scwin.mode == 'I') {
        //전송전 입력모드
        $c.stf.showObj(label_24, false);

        //for(var i=1;i<=3;i++) {
        for (var i = 1; i < 3; i++) {
            if (halt_yn == 'N' && i > 1) {
                eval("txb_NOTI_EMP_NM" + i).style.backgroundColor = '#b9d4f7';
                eval("txb_NOTI_DDTM" + i).style.backgroundColor = '#b9d4f7';
                eval("txb_ACPT_EMP_NM" + i).style.backgroundColor = '#b9d4f7';
                eval("txb_REMK" + i).style.backgroundColor = '#b9d4f7';
                eval("txb_DISCLS_DDTM" + i).style.backgroundColor = '#b9d4f7';
                $c.stf.setObjectValue(eval("txb_NOTI_EMP_NM" + i), '');
                $c.stf.setObjectValue(eval("txb_NOTI_DDTM" + i), '');
                $c.stf.setObjectValue(eval("txb_DEP_CD" + i), '');
            } else {
                eval("txb_NOTI_EMP_NM" + i).style.backgroundColor = '#FFFFFF';
                eval("txb_NOTI_DDTM" + i).style.backgroundColor = '#FFFFFF';
                eval("txb_ACPT_EMP_NM" + i).style.backgroundColor = '#FFFFFF';
                eval("txb_REMK" + i).style.backgroundColor = '#FFFFFF';
                eval("txb_DISCLS_DDTM" + i).style.backgroundColor = '#FFFFFF';

                //부서코드 셋팅
                if (i == 2) {
                    $c.stf.setObjectValue(eval("txb_DEP_CD" + i), '2430');
                }
                //else if(i==3)  {

                // 상품관리팀 20130415 상품 관리팀 제외.

                //setObjectValue(eval("txb_DEP_CD"+i),'2B20');

                //}

            } //if

        } //for

    } else if (scwin.mode = 'T') {

    }
};
scwin.fn_read = function() {
    var noti_seq = '';
    var isur_cd = '';
    if (scwin.key_row != '') {
        noti_seq = frame.opener.dts_Grid.getCellData(scwin.key_row, "NOTI_SEQ");
        isur_cd = frame.opener.dts_Grid.getCellData(scwin.key_row, "ISUR_CD");
    }
    var url = "/OnlineNotice.do?method=readDetailTelNoticeMaster";
    url += "&NOTI_SEQ=" + noti_seq;
    url += "&ISUR_CD=" + isur_cd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Master.DataID = encodeURI(url);
    dts_Master.Reset();
    url = "/OnlineNotice.do?method=readDetailTelNoticeSub";
    url += "&NOTI_SEQ=" + noti_seq;
    url += "&ISUR_CD=" + isur_cd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Sub.DataID = encodeURI(url);
    dts_Sub.Reset();
};
scwin.fn_Del = function() {
    $c.stf.setObjectValue(txb_EMP_NO, scwin.gEmpNo);
    var res = window.confirm("[삭제]하시겠습니까?");
    if (res) {
        gLastJob = "삭제";
        var url = "/OnlineNotice.do?method=deleteOnlineNotice" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Sub)";
        trs_Save.post();
    }
};
scwin.fn_CheckForm = function() {
    var flag = true;
    var isur_cd = "";
    var contn = "";
    var halt_yn = "";
    var remk = "";
    isur_cd = $c.stf.getObjectValue(txb_ISUR_CD);
    contn = $c.stf.getObjectValue(txb_INQDISCLS_REQ_CONTN);
    halt_yn = $c.stf.getObjectValue(rdo_HALT_YN);
    remk = $c.stf.getObjectValue(txb_REMK);
    if (isur_cd == '') {
        $c.win.alert("회사를 선택해 주세요.");
        return false;
    }
    if (halt_yn == '') {
        $c.win.alert("매매거래정지여부를 선택해주세요.");
        return false;
    }
    if (contn == '') {
        $c.win.alert("내용을 입력해주세요.");
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_INQDISCLS_REQ_CONTN, 100, "내용")) {
        txb_INQDISCLS_REQ_CONTN.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_REMK, 100, "비고")) {
        txb_REMK.focus();
        return false;
    }
    var no_array;
    if ($c.stf.getObjectValue(rdo_HALT_YN) == 'Y') {
        no_array = new Array("1", "2");
    } else {
        no_array = new Array("1");
    }
    for (var i = 1; i <= no_array.length; i++) {
        if ($c.stf.getObjectValue(eval("txb_NOTI_EMP_NM" + no_array[i - 1])) == '') {
            $c.win.alert("통보자를 입력해주세요.");
            return false;
        }
        if ($c.stf.getObjectValue(eval("txb_NOTI_DDTM" + no_array[i - 1])) == '') {
            $c.win.alert("통보시각을 입력해주세요.");
            return false;
        }
    }
    return flag;
};
scwin.checkMaxLength = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

