*/
scwin.fn_Transmit = function() {
    var rtn = false;
    $c.stf.setObjectValue(txb_EMP_NO, scwin.gEmpNo);
    var noti_seq = $c.stf.getObjectValue(txb_NOTI_SEQ);
    if (noti_seq == '') {
        $c.stf.setObjectValue(txb_MODE, "TI");
    } else {
        $c.stf.setObjectValue(txb_MODE, "TU");
    }
    rtn = scwin.fn_CheckForm();
    if (rtn) {
        var res = window.confirm("[저장]하시겠습니까?");
        if (res) {
            $c.stf.setObjectValue(txb_COM_ABBRV, '');
            $c.stf.setObjectValue(txb_DISCLS_DDTM1, '');
            gLastJob = "저장";
            var url = "/OnlineNotice.do?method=saveTelNotice" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputSub=dts_Sub)";
            trs_Save.post();
        }
    }
};
scwin.fn_delete = function(row_num) {
    eval("txb_COM_ABBRV" + row_num).setValue("");
    eval("txb_INQDISCLS_REQ_CONTN" + row_num).setValue("");
    $c.stf.setObjectValue(eval("rdo_ONLN_NOTI_YN" + row_num), '');
    eval("txb_ISUR_CD" + row_num).setValue("");
    eval("txb_CHRG_NM" + row_num).setValue("");
};
scwin.afterExec = function(isur_cd, ld_mkt_tp_cd) {
    $c.stf.setObjectValue(txb_LD_MKT_TP_CD, ld_mkt_tp_cd);
    var url = "/OnlineNotice.do?method=getDepCd";
    url += "&ISUR_CD=" + isur_cd;
    dts_dep.DataID = encodeURI(url);
    dts_dep.Reset();
    $c.stf.setObjectValue(rdo_HALT_YN, '');
};
scwin.fn_openDiscls = async function(num) {
    fn_SetPar = fn_setDiscls;
    link_num = num;
    if (scwin.gDepCd != '5B10') {
        //alert("시장감시부에서만 공시연결할 수 있습니다.");
        return;
    }
    if ($c.stf.getObjectValue(eval("txb_ACPT_EMP_NO" + num)) != '') {
        await $c.frame.CreateDialogFrame("wndDiscls|ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD), "/dsclmgt/ULDSTF30007.gfm", "공시선택", 100, 100, 10, 20, "window");
    } else {
        $c.win.alert("접수자를 먼저 입력해주세요.");
    }
};
scwin.fn_setDiscls = function(arrPar) {
    //공시팝업에서 공시선택시 값 셋팅.
    //alert("arrPar[0] : " + arrPar[0] + " : arrPar[1] : " + arrPar[1] + " :arrPar[2] : " + arrPar[2]);
    var acpt_no = arrPar[0];
    var discls_title = arrPar[1];
    var discls_date = arrPar[2];
    discls_date = discls_date.substring(0, 4) + "-" + discls_date.substring(4, 6) + "-" + discls_date.substring(6, 8) + " " + discls_date.substring(8, 10) + ":" + discls_date.substring(10, 12) + "(" + discls_title + ")";
    $c.stf.setObjectValue(eval("txb_ACPT_NO" + link_num), acpt_no);
    $c.stf.setObjectValue(eval("txb_DISCLS_DDTM" + link_num), discls_date);
};
scwin.personSearch_Rtn = function(emp_no, emp_nm) {
    js_emp_no.setValue(emp_no);
    js_emp_nm.setValue(emp_nm);
};
scwin.fn_openPerson = async function(obj1, obj2, no, gubun) {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == '') {
        $c.win.alert("회사를 먼저 선택해주세요.");
        return;
    }
    if ($c.stf.getObjectValue(rdo_HALT_YN) == '') {
        $c.win.alert("매매거래정지여부를 먼저 선택해주세요.");
        return;
    }
    if (no > 1 && ($c.stf.getObjectValue(rdo_HALT_YN) == 'N' && $c.stf.getObjectValue(rdo_HALT_YN) != '1')) {
        return;
    }
    scwin.js_emp_no = obj1;
    scwin.js_emp_nm = obj2;
    if (gubun == 'A') {
        scwin.key_dep_cd = $c.stf.getObjectValue(eval("txb_DEP_CD" + no));
    } else {
        scwin.key_dep_cd = "5B10";
    }
    await $c.frame.CreateDialogFrame("DLG_EMP_SEL", "/dsclproc/ULDSTF10808.gfm", "담당자선택", 10, 10, 360 + 5, 400 + 30, "window");
};
scwin.fn_inputTime = async function(no, gubun) {
    //gubun 'N' =  통보시각, 'A' =  접수시각
    scwin.time_no = no;
    scwin.time_field = gubun;
    if (no > 1 && ($c.stf.getObjectValue(rdo_HALT_YN) == 'N' && $c.stf.getObjectValue(rdo_HALT_YN) != '1')) {
        return;
    }
    if (scwin.mode == 'I' && gubun == 'N') {
        //전송전 입력모드
        await $c.frame.CreateDialogFrame("DLG_TIME", "/dsclproc/ULDSTF10809.gfm", "시간입력", 10, 10, 360 + 5, 180, "window");
    } else if (scwin.mode == 'T' && gubun == 'A') {
        if (scwin.gDepCd == $c.stf.getObjectValue(eval("txb_DEP_CD" + no))) {
            await $c.frame.CreateDialogFrame("DLG_TIME", "/dsclproc/ULDSTF10809.gfm", "시간입력", 10, 10, 360 + 5, 180, "window");
        }
    }
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
    $c.win.alert(msg);
    var fr_fn_Search = $c.frame.path("../").fn_Search;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_ABBRV);
};
scwin.txb_NOTI_EMP_NM1_ondblclick = function() {
    if (scwin.mode == 'I') {
        scwin.fn_openPerson(txb_NOTI_EMP_NO1, txb_NOTI_EMP_NM1, '1', 'T');
    }
};
scwin.txb_NOTI_EMP_NM2_ondblclick = function() {
    if (scwin.mode == 'I') {
        scwin.fn_openPerson(txb_NOTI_EMP_NO2, txb_NOTI_EMP_NM2, '2', 'T');
    }
};
scwin.txb_ACPT_EMP_NM1_ondblclick = function() {
    scwin.fn_openPerson(txb_ACPT_EMP_NO1, txb_ACPT_EMP_NM1, '1', 'A');
};
scwin.txb_ACPT_EMP_NM2_ondblclick = function() {
    scwin.fn_openPerson(txb_ACPT_EMP_NO2, txb_ACPT_EMP_NM2, '2', 'A');
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Del();
};
scwin.btn_Transmit_onclick = function() {
    scwin.fn_Transmit();
};
scwin.rdo_HALT_YN_OnSelChange = function() {
    scwin.fn_setPage();
};
scwin.txb_NOTI_DDTM1_ondblclick = function() {
    scwin.fn_inputTime('1', 'N');
};
scwin.txb_NOTI_DDTM2_ondblclick = function() {
    scwin.fn_inputTime('2', 'N');
};
scwin.txb_DISCLS_DDTM1_ondblclick = function() {
    scwin.fn_openDiscls('1');
};
scwin.txb_DISCLS_DDTM2_ondblclick = function() {
    scwin.fn_openDiscls('2');
};
scwin.gform_onload = function() {
    //PanelToGroupBox(panel_1);
    scwin.fn_read();
    setTimeout("fn_init()", 1000); //데이터 로딩시간이 있어 1초후 화면초기화 작업한다.

};
